CREATE OR REPLACE FUNCTION nexus.text_gate_probe_384( p_text text, p_collections text[], p_where jsonb, p_where_path text, p_cap int ) RETURNS SETOF bytea LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT c.chash FROM nexus.chunks c WHERE c.collection = ANY(p_collections) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) AND (c.chunk_tsv @@ plainto_tsquery('english', p_text) OR p_text OPERATOR(nexus.<%) c.chunk_text) LIMIT p_cap $$;
