CREATE OR REPLACE FUNCTION nexus.text_gate_probe_384( p_text text, p_collections text[], p_where jsonb, p_where_path text, p_cap int ) RETURNS SETOF bytea LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT c.chash FROM nexus.chunks c WHERE c.collection = ANY(p_collections) AND (NOT EXISTS (SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash AND d.deleted_at IS NOT NULL AND NOT EXISTS (SELECT 1 FROM nexus.catalog_document_chunks m2 JOIN nexus.catalog_documents d2 ON d2.tenant_id = m2.tenant_id AND d2.tumbler = m2.doc_id WHERE m2.tenant_id = m.tenant_id AND m2.chash = m.chash AND d2.deleted_at IS NULL))) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) AND (c.chunk_tsv @@ plainto_tsquery('english', p_text) OR p_text OPERATOR(nexus.<%) c.chunk_text) LIMIT p_cap $$;
